<template><view class="page"><PageHead title="收货地址"/><view class="content"><view v-for="a in addresses" :key="a.id" class="card"><view @click="select(a)"><view class="bold">{{a.detail}}</view><view class="subtitle">{{a.contact}} {{a.phone}}</view></view><view class="between" style="margin-top:22rpx"><text class="small link" @click="edit(a)">编辑</text><text class="small muted" @click="remove(a)">删除</text></view></view><view v-if="!addresses.length&&!editing" class="empty"><view class="empty-symbol">⌖</view>添加地址，让美味找到你</view><view v-if="editing" class="card"><view class="title" style="font-size:30rpx">{{form.id?'编辑地址':'新增地址'}}</view><view style="margin-top:25rpx" class="label">联系人</view><input v-model="form.contact" placeholder="怎么称呼你" class="field" maxlength="50"/><text class="label">联系电话</text><input v-model="form.phone" placeholder="11位手机号" type="number" maxlength="11" class="field"/><text class="label">详细地址</text><input v-model="form.detail" @input="form.latitude=null;form.longitude=null" placeholder="校区、宿舍楼、楼层和门牌号" class="field" maxlength="250"/><view class="subtitle">请在地图标记实际收货点，商家会据此校验配送范围。修改地址后请重新选点。</view><button class="btn" style="margin-bottom:16rpx" :disabled="locating" @click="chooseMap">地图选收货点</button><button class="btn" :loading="locating" :disabled="locating" @click="locate">{{form.latitude!=null?'重新定位收货点':'在收货处定位'}}</button><view v-if="form.latitude!=null" class="subtitle">✓ 已标记收货点</view><view v-if="locationError" class="error">{{locationError}}</view><button class="btn" style="margin-top:20rpx" :loading="busy" :disabled="busy||locating" @click="save">保存地址</button></view><button v-else class="btn" @click="edit({})">＋ 新增收货地址</button></view></view></template>
<script setup>
import {ref} from 'vue';import {acquire} from '../../lib/location';
const locating=ref(false),locationError=ref('');async function locate(){locating.value=true;locationError.value='';try{const p=await acquire();form.value.latitude=p.latitude;form.value.longitude=p.longitude}catch{locationError.value='定位失败，请检查设备定位权限后重试'}finally{locating.value=false}}
import {onLoad,onShow} from '@dcloudio/uni-app';import PageHead from '../../components/PageHead.vue';import {request,ensureLogin,confirm,toast} from '../../lib/api';const addresses=ref([]),editing=ref(false),form=ref({}),busy=ref(false),selectMode=ref(false);async function load(){try{await ensureLogin();addresses.value=await request('/addresses')}catch{}}function edit(a){mapNonce='';locationError.value='';form.value={...a};editing.value=true}function select(a){if(!selectMode.value)return;uni.setStorageSync('food-selected-address',a.id);uni.navigateBack()}async function save(){busy.value=true;try{await request('/addresses','POST',form.value);editing.value=false;await load();toast('地址已保存')}catch{}finally{busy.value=false}}async function remove(a){if(await confirm('删除这个地址？'))try{await request('/addresses/'+a.id,'DELETE');load()}catch{}}onLoad(o=>{selectMode.value=o.select==='1';load()});

import {fromGcj02} from '../../lib/map-point.mjs';let mapNonce='';
async function chooseMap(){locationError.value='';
 // #ifdef H5
 mapNonce=Date.now()+'-'+Math.random().toString(36).slice(2);uni.removeStorageSync('food-map-result');uni.navigateTo({url:'/pages/map/index?nonce='+mapNonce+(form.value.latitude!=null?'&latitude='+form.value.latitude+'&longitude='+form.value.longitude:'')});
 // #endif
 // #ifndef H5
 locating.value=true;const current=form.value;uni.chooseLocation({success:p=>{if(current!==form.value)return;try{Object.assign(form.value,fromGcj02(p));if(!form.value.detail)form.value.detail=(p.address||'')+(p.name||'')}catch(e){locationError.value=e.message}},fail:()=>locationError.value='未能选取位置，请检查小程序定位权限或使用现场定位',complete:()=>locating.value=false});
 // #endif
}
onShow(()=>{const p=uni.getStorageSync('food-map-result');if(p&&mapNonce&&p.nonce===mapNonce&&editing.value){form.value.latitude=p.latitude;form.value.longitude=p.longitude;uni.removeStorageSync('food-map-result');mapNonce=''}});
</script>
